<?php
declare(strict_types=1);
namespace App;
final class LandingRenderer {
 public static function money(?float $value):string {return $value===null?'Consulta el precio':'$ '.number_format($value,round($value,2)===floor($value)?0:2,',','.').' COP';}
 public static function icon(string $name):string {$paths=['check'=>'m5 12 4 4L19 6','box'=>'m3 7 9-4 9 4-9 4-9-4v10l9 4 9-4V7 M12 11v10','send'=>'m22 2-7 20-4-9-9-4 20-7ZM11 13 22 2','chat'=>'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z','arrow'=>'M5 12h14 m-6-6 6 6-6 6','link'=>'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2','grid'=>'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'];return '<svg aria-hidden="true" class="block-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'.($paths[$name]??$paths['check']).'"/></svg>';}
 public static function image(string $url,string $alt='',bool $hero=false):string {return $url!==''?'<img src="'.Support::escape($url).'" alt="'.Support::escape($alt).'" '.($hero?'fetchpriority="high"':'loading="lazy"').' decoding="async">':'<div class="block-image-empty">Sin imagen disponible</div>';}
 public static function cta(array $c,string $text=''):string {return '<button type="button" class="primary buy-trigger" data-buy>'.Support::escape($text?:$c['visual']['buttonText']).self::icon('arrow').'</button>';}
 public static function purchase(array $c,string $text=''):string {
  $e=fn($v)=>Support::escape($v);$o=$c['commerce'];$price=self::money($c['publicPrice']);$html='<div class="purchase-box"><div class="purchase-price">'.($o['previousPrice']!==null?'<del>'.self::money($o['previousPrice']).'</del>':'').'<strong>'.$e($price).'</strong></div>';
  if($o['quantityEnabled'])$html.='<div class="buy-row"><div class="quantity-control"><button type="button" data-quantity-step="-1" aria-label="Disminuir cantidad">−</button><label><span class="sr-only">Cantidad</span><input type="number" data-quantity min="1" max="'.$o['maxQuantity'].'" value="1" inputmode="numeric"></label><button type="button" data-quantity-step="1" aria-label="Aumentar cantidad">+</button></div>'.self::cta($c,$text).'</div>';
  else $html.=self::cta($c,$text);
  $messages='';foreach(['Shipping'=>'shipping','Delivery'=>'delivery','Payment'=>'payment'] as $flag=>$key)if($o['show'.$flag]&&$o[$key]!=='')$messages.='<p>'.self::icon($key==='shipping'?'send':'check').$e($o[$key]).'</p>';
  return $html.($messages?'<div class="purchase-messages">'.$messages.'</div>':'').'</div>';
 }
 public static function gallery(array $images,string $title,string $variant,bool $hero=false):string {
  if(!$images)return self::image('',$title);
  if($hero||$variant==='thumbnails'){
   $html='<div class="block-gallery" data-gallery-group><button type="button" class="block-gallery-main" data-zoom aria-label="Ampliar imagen">'.self::image($images[0],$title,$hero).'</button><div class="block-thumbnails">';
   foreach($images as $i=>$url)$html.='<button type="button" data-gallery="'.Support::escape($url).'" aria-pressed="'.($i===0?'true':'false').'" aria-label="Ver imagen '.($i+1).'">'.self::image($url,'').'</button>';return $html.'</div></div>';
  }
  $html='<div class="block-gallery-images">';foreach($images as $i=>$url)$html.='<button type="button" data-zoom aria-label="Ampliar imagen '.($i+1).'">'.self::image($url,$title).'</button>';return $html.'</div>'.($variant==='carousel'?'<div class="carousel-controls"><button type="button" data-carousel="-1" aria-label="Imágenes anteriores">←</button><button type="button" data-carousel="1" aria-label="Más imágenes">→</button></div>':'');
 }
 public static function items(array $b):string {
  $e=fn($v)=>Support::escape($v);$type=$b['type'];$variant=$b['variant'];$items=array_values(array_filter($b['data']['items']??[],fn($i)=>$i['visible']));$html='';
  if(!$items)return '';
  foreach($items as $i=>$item){
   $title=$e($item['title']);$description=in_array($type,['faq','policies'],true)?$item['description']:nl2br($e($item['description']));$image=$item['image']?self::image($item['image'],$item['title']):'';
   if(in_array($type,['faq','policies'],true)&&in_array($variant,['accordion','compact','columns'],true)){$html.='<details class="block-accordion"><summary>'.$title.'<span aria-hidden="true">+</span></summary><div class="accordion-content rich-content">'.$description.'</div></details>';continue;}
   if($type==='specs'){$html.='<div class="spec-row"><dt>'.$title.'</dt><dd>'.$e($item['value']?:$item['description']).'</dd></div>';continue;}
   $lead=$image?'<div class="item-image">'.$image.'</div>':(in_array($type,['usage'],true)||in_array($variant,['numbered','steps'],true)?'<span class="item-number">'.($i+1).'</span>':(in_array($variant,['checks','icons','cards','grid','horizontal','list'],true)?'<span class="item-icon">'.self::icon($variant==='checks'?'check':$item['icon']).'</span>':''));
   $rating=$type==='testimonials'&&$item['rating']!==null?'<span class="testimonial-rating" aria-label="'.$item['rating'].' de 5">'.$item['rating'].' / 5</span>':'';
   $html.='<li class="block-item">'.$lead.'<div>'.$rating.'<h3>'.$title.($type==='includes'&&$item['quantity']!==''?' <small>'.$e($item['quantity']).'</small>':'').'</h3>'.($description!==''?'<div class="item-description rich-content">'.$description.'</div>':'').($item['date']!==''?'<time datetime="'.$e($item['date']).'">'.$e($item['date']).'</time>':'').'</div></li>';
  }
  if($type==='specs')return $variant==='accordion'?'<details class="block-accordion"><summary>Ver especificaciones <span aria-hidden="true">+</span></summary><dl class="block-specs">'.$html.'</dl></details>':'<dl class="block-specs">'.$html.'</dl>';
  if(in_array($type,['faq','policies'],true)&&in_array($variant,['accordion','compact','columns'],true))return '<div class="block-faq">'.$html.'</div>';
  return '<'.(in_array($variant,['numbered','steps'],true)||$type==='usage'?'ol':'ul').' class="block-items">'.$html.'</'.(in_array($variant,['numbered','steps'],true)||$type==='usage'?'ol':'ul').'>'.($variant==='carousel'?'<div class="carousel-controls"><button type="button" data-carousel="-1" aria-label="Anteriores">←</button><button type="button" data-carousel="1" aria-label="Siguientes">→</button></div>':'');
 }
 public static function related(array $ids,string $owner):array {
  $out=[];foreach($ids as $id){$r=Database::one("SELECT * FROM landing_pages WHERE id=? AND user_id=? AND status='published'",[$id,$owner]);if($r){$r=Landing::published($r);$out[]=['url'=>'/p/'.$r['slug'],'title'=>$r['content']['title'],'image'=>$r['content']['images'][0]??'','price'=>$r['content']['publicPrice']];}}return $out;
 }
 public static function block(array $b,array $c,string $owner):string {
  if(!$b['visible'])return '';$e=fn($v)=>Support::escape($v);$d=$b['data'];$type=$b['type'];$variant=$b['variant'];$heading=($d['title']??'')!==''?'<h2>'.$e($d['title']).'</h2>':'';$subtitle=($d['subtitle']??'')!==''?'<p class="block-subtitle">'.$e($d['subtitle']).'</p>':'';$text=$d['text']??'';$html='';
  if($type==='hero'){
   $images=$d['images']?:$c['images'];if($d['image'])$images=[$d['image'],...array_filter($images,fn($url)=>$url!==$d['image'])];
   $html='<div class="hero-media">'.self::gallery($images,$c['title'],'thumbnails',true).'</div><div class="hero-copy">'.($d['label']?'<p class="hero-label">'.$e($d['label']).'</p>':'').'<h1>'.$e($d['title']?:$c['title']).'</h1>'.$subtitle.'<div class="rich-content hero-description">'.($text?:nl2br($e($c['description']))).'</div>'.self::items($b).self::purchase($c,$d['ctaText']).'</div>';
  }elseif($type==='gallery'){
   $gallery=self::gallery($d['images']?:$c['images'],$c['title'],$variant==='image-text'?'thumbnails':$variant);
   $html=$variant==='image-text'?'<div>'.$gallery.'</div><div>'.$heading.$subtitle.'<div class="rich-content">'.$text.'</div></div>':$heading.$subtitle.$gallery.($text?'<div class="rich-content">'.$text.'</div>':'');
  }elseif($type==='imageText'){$html='<div class="editorial-image">'.self::image($d['image']?:($c['images'][0]??''),$d['title']).'</div><div>'.$heading.$subtitle.'<div class="rich-content">'.$text.'</div>'.self::items($b).($d['ctaText']?self::cta($c,$d['ctaText']):'').'</div>';
  }elseif($type==='includes'&&$variant==='image-text'){$html='<div class="editorial-image">'.self::image($d['image']?:($c['images'][0]??''),$d['title']).'</div><div>'.$heading.$subtitle.self::items($b).'</div>';
  }elseif($type==='cta'){$html=($d['image']?'<div class="cta-image">'.self::image($d['image'],$d['title']).'</div>':'').'<div>'.$heading.$subtitle.($text?'<div class="rich-content">'.$text.'</div>':'').self::purchase($c,$d['ctaText']).'</div>';
  }elseif($type==='shipping'){
   $rows='';foreach(['coverage'=>'Cobertura','cost'=>'Costo de envío','delivery'=>'Tiempo de entrega','carrier'=>'Transportadora','conditions'=>'Condiciones'] as $key=>$label)if($d[$key]!=='')$rows.='<li class="shipping-item">'.self::icon('send').'<div><h3>'.$label.'</h3><p>'.$e($d[$key]).'</p></div></li>';
   $inside=($text?'<div class="rich-content">'.$text.'</div>':'').'<ul class="shipping-items">'.$rows.'</ul>';$html=$heading.($variant==='accordion'?'<details class="block-accordion"><summary>Ver condiciones de entrega <span aria-hidden="true">+</span></summary>'.$inside.'</details>':$inside);
  }elseif($type==='related'){
   $html=$heading.$subtitle.'<div class="related-products">';foreach(self::related($d['relatedIds'],$owner) as $product)$html.='<a class="related-card" href="'.$e($product['url']).'">'.self::image($product['image'],$product['title']).'<h3>'.$e($product['title']).'</h3><p>'.self::money($product['price']).'</p></a>';$html.='</div>';if($variant==='carousel')$html.='<div class="carousel-controls"><button type="button" data-carousel="-1" aria-label="Productos anteriores">←</button><button type="button" data-carousel="1" aria-label="Más productos">→</button></div>';
  }elseif($type==='divider'){$html='<div class="page-divider" aria-hidden="true"></div>';
  }else{$html=$heading.$subtitle.($text?'<div class="rich-content">'.$text.'</div>':'').(isset($d['items'])?self::items($b):'');}
  $classes='landing-block type-'.$type.' variant-'.$variant;foreach($b['style'] as $key=>$value)$classes.=' '.$key.'-'.$value;
  return '<section id="section-'.$e($b['id']).'" class="'.$classes.'" data-block-id="'.$e($b['id']).'"><div class="block-inner">'.$html.'</div></section>';
 }
 public static function render(array $row,bool $preview=false,string $notice=''):string {
  $r=$preview?Landing::decode($row):Landing::published($row);$c=$r['content'];$v=$c['visual'];$e=fn($s)=>Support::escape($s);$url=rtrim(Support::env('APP_URL'),'/').'/p/'.$r['slug'];
  if($preview&&isset($_GET['expires'],$_GET['signature'])){
   $sign=function(string $image){return str_starts_with($image,rtrim(Support::env('APP_URL'),'/').'/media/')?$image.'?'.http_build_query(['expires'=>$_GET['expires'],'signature'=>$_GET['signature']]):$image;};$c['images']=array_map($sign,$c['images']);foreach($c['blocks'] as &$block){if(isset($block['data']['image']))$block['data']['image']=$sign($block['data']['image']);if(isset($block['data']['images']))$block['data']['images']=array_map($sign,$block['data']['images']);foreach($block['data']['items']??[] as $key=>$item)$block['data']['items'][$key]['image']=$sign($item['image']);}unset($block);
  }
  $title=$c['seoTitle']?:$c['title'];$description=$c['seoDescription']?:mb_substr($c['description'],0,300);$html='';$hasHero=false;
  foreach($c['blocks'] as $b){$section=self::block($b,$c,$r['user_id']??'');if($b['visible']&&$b['type']==='hero'){if($hasHero)$section=str_replace(['<h1>','</h1>'],['<h2>','</h2>'],$section);$hasHero=true;}$html.=$section;}
  $image=$c['images'][0]??'';$price=self::money($c['publicPrice']);
  $form=$preview?'<p class="notice">Previsualización privada. El formulario está desactivado.</p>':'<form id="lead-form" method="post" action="/p/'.$e($r['slug']).'/lead"><input type="hidden" name="csrf" value="'.$e($_SESSION['csrf']??'').'"><input type="hidden" name="idempotency_key" value="'.Support::uuid().'"><input type="hidden" name="quantity" value="1" data-lead-quantity><label class="trap" aria-hidden="true">Sitio web<input name="website" tabindex="-1" autocomplete="off"></label><div class="form-grid"><label>Nombre<input name="first_name" maxlength="100" required autocomplete="given-name"></label><label>Apellido<input name="last_name" maxlength="100" required autocomplete="family-name"></label><label>Email<input name="email" type="email" maxlength="254" required autocomplete="email"></label><label>Teléfono<input name="phone" type="tel" maxlength="30" required autocomplete="tel"></label></div><p>Al enviar autorizas que te contactemos para atender tu solicitud sobre este producto.</p><button class="primary" type="submit">Enviar solicitud</button><p id="lead-status" role="status"></p></form>';
  $modal='<dialog id="purchase-dialog" aria-labelledby="purchase-title"><div class="purchase-modal-top"><h2 id="purchase-title">Solicita tu pedido</h2><button type="button" data-close-purchase aria-label="Cerrar formulario">×</button></div><div class="purchase-modal-content"><div class="order-summary">'.($image?self::image($image,$c['title']):'').'<div><h3>'.$e($c['title']).'</h3><p>Precio unitario: '.$e($price).'</p><p>Cantidad: <strong data-summary-quantity>1</strong></p></div></div><div class="order-total"><span>Total del producto</span><strong data-summary-total>'.$e($price).'</strong></div><p class="order-note">El equipo confirmará disponibilidad y condiciones. Esto es una solicitud, no un pago ni una compra confirmada.</p>'.$form.'</div></dialog>';
  $sticky=$c['commerce']['stickyMobile']?'<div class="mobile-purchase"><strong>'.$e($price).'</strong>'.self::cta($c).'</div>':'';$wa=$v['whatsapp']?'<a class="whatsapp" rel="noopener noreferrer" href="https://wa.me/'.$e($v['whatsapp']).'?text='.rawurlencode('Hola, quiero información sobre '.$c['title']).'">Consultar por WhatsApp</a>':'';
  return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($title).'</title><meta name="description" content="'.$e($description).'"><meta name="robots" content="'.($preview?'noindex,nofollow':'index,follow').'"><link rel="canonical" href="'.$e($url).'"><meta property="og:title" content="'.$e($title).'"><meta property="og:description" content="'.$e($description).'"><meta property="og:url" content="'.$e($url).'"><meta property="og:type" content="product">'.($image?'<meta property="og:image" content="'.$e($image).'">':'').'<link rel="stylesheet" href="/landing.css"><link rel="stylesheet" href="/blocks.css"></head><body class="block-page'.($sticky?' has-sticky-buy':'').'" data-preview="'.($preview?'true':'false').'" data-price="'.$e($c['publicPrice']===null?'':(string)$c['publicPrice']).'" data-max-quantity="'.($c['commerce']['quantityEnabled']?$c['commerce']['maxQuantity']:1).'" style="--primary:'.$e($v['primaryColor']).';--paper:'.$e($v['backgroundColor']).'"><header><a class="brand" href="'.$e($url).'">zenzales<span>.</span></a><span>'.($preview?'Borrador · vista privada':'Información del producto').'</span></header><main>'.(!$hasHero?'<h1 class="sr-only">'.$e($c['title']).'</h1>':'').($notice?'<p class="notice" role="status">'.$e($notice).'</p>':'').$html.'</main>'.$wa.'<footer>Zenzales · Consulta sobre este producto</footer>'.$modal.$sticky.'<dialog id="image-zoom" aria-label="Imagen ampliada"><button type="button" data-close-zoom aria-label="Cerrar imagen">×</button><img alt="Imagen ampliada del producto"></dialog><script src="/landing-assets/landing-runtime.js" defer></script></body></html>';
 }
}
